# Meeting 1: part 7 (common factor, factoring) and part 8 (summary, guided exercises, home practice).

# ================================================================ part 7
opener(7, 'הוצאת גורם משותף ופירוק לגורמים', 'איך חוזרים מסכום של איברים אל מכפלה?',
       ['פירוק לגורמים: הפעולה ההפוכה לפתיחת סוגריים', 'מוצאים את הגורם המשותף הגדול ביותר: מספר ואותיות', 'פירוק בעזרת הנוסחה $a^2 - b^2$', 'בודקים כל פירוק בפתיחת סוגריים'], 12)

S('s-fac-idea', 'הדרך חזרה', 'הדרך חזרה: מסכום למכפלה',
  '<div class="row eq2"><div class="col">'
  + CARD(P('**בכיתה אחת 12 תלמידים, ובכיתה אחרת 18. המורה מחלקת את כולם לקבוצות של 6. כמה קבוצות יש?**')
         + ST(1, VEQ('12+18 = {1|6}*2+{1|6}*3') + P('כל מספר נכתב כמכפלה של 6.'))
         + ST(2, VEQ('{1|6}*2+{1|6}*3 = {1|6}(2+3)') + P('ה-6 משותף לשני המחוברים, ואפשר להוציא אותו: 5 קבוצות של 6.')), cls='qstem')
  + ST(3, '<div class="twoway"><div class="tw-e">' + MI('5(10x^2+x-3)') + '</div><div class="tw-a"><span class="a1">פתיחת סוגריים &#9664;</span><span class="a2">&#9654; הוצאת גורם משותף</span></div><div class="tw-e">' + MI('50x^2+5x-15') + '</div></div>', cls='card pop')
  + '</div><div class="col">'
  + DEF('גורם (Factor)', 'כל אחד מהמספרים או מהביטויים שמוכפלים זה בזה.', 'ב-$6(2+3)$ יש שני גורמים: 6, והסוגריים.', 4, trm='factor', cls='mini')
  + DEF('גורם משותף (Common factor)', 'מספר או אות שמופיעים בכפל בכל אחד מאיברי הביטוי.', 'ב-$6*2 + 6*3$ הגורם המשותף הוא 6.', 5, trm='cfactor', cls='mini')
  + DEF('פירוק לגורמים (Factoring)', 'כתיבה של סכום בצורת מכפלה. זו הפעולה ההפוכה לפתיחת סוגריים.', '$12 + 18 = 6(2+3)$.', 6, trm='factoring', cls='mini')
  + '</div></div>', kick=KICK('מדוגמה אל ההגדרה'))

WORK('s-fac-work', 'מסבירים יחד', 'הוצאת גורם משותף: מספר',
     ['**הוציאו גורם משותף מהביטוי הבא.**'],
     [('~50, 5, 15', 'מחפשים את המספר הגדול ביותר שמחלק את שלושת המקדמים. זה 5.'),
      ('~', 'האם יש אות שמופיעה בכל האיברים? לא: באיבר $-15$ אין $x$. לכן הגורם המשותף הוא 5 בלבד.'),
      ('={1|5}*10x^2+{1|5}*x-{1|5}*3', 'כותבים כל איבר כמכפלה של 5 במה שנשאר.'),
      ('={1|5}(10x^2+x-3)', 'מוציאים את ה-5 אל מחוץ לסוגריים.'),
      ('5(10x^2+x-3) = 50x^2+5x-15', 'בדיקה: פותחים את הסוגריים, ומקבלים את הביטוי המקורי.')],
     expr='50x^2+5x-15', size='sm',
     tip='כל פירוק אפשר לבדוק. פותחים את הסוגריים, וצריך לחזור לביטוי שממנו התחלנו.')

WORK('s-fac-letters', 'מסבירים יחד', 'הוצאת גורם משותף: מספר ואות',
     ['**הוציאו גורם משותף מהביטוי הבא.**'],
     [('~', 'המספר הגדול ביותר שמחלק את שני המקדמים: 4.'),
      ('x^3 = x^2*x', 'האות $x$ מופיעה בשני האיברים. מוציאים אותה בחזקה הנמוכה מבין השתיים: $x^2$.'),
      ('={1|4x^2}*x-{1|4x^2}*1', 'כותבים כל איבר כמכפלה של $4x^2$ במה שנשאר. האיבר השני הוא $4x^2*1$.'),
      ('={1|4x^2}(x-1)', 'מוציאים את הגורם המשותף.')],
     expr='4x^3-4x^2',
     tip='כשמוציאים איבר שלם, נשאר במקומו 1, ולא אפס. בלי ה-1, פתיחת הסוגריים לא תחזיר את הביטוי המקורי.')

MC1('s-fac-mc', 'בדיקה: גורם משותף', 'מהו הגורם המשותף הגדול ביותר של הביטוי $4x^3 - 2x^2 + 8x$?', ['$2x$', '2', '$4x$', '$2x^2$'],
    'המספר הגדול ביותר שמחלק את 4, 2 ו-8 הוא 2. האות $x$ מופיעה בכל האיברים, והחזקה הנמוכה ביותר שלה היא $x$. לכן הגורם המשותף הוא $2x$.', art='robot')

TRYS('s-fac-try', 'תרגול: גורם משותף', 'תרגול: הוציאו גורם משותף', [
    TRY('t-g1', 'פרקו: $6x + 9$', '3(2x+3)', ['מהו המספר הגדול ביותר שמחלק גם את 6 וגם את 9?'], [('={1|3}*2x+{1|3}*3', 'כל איבר כמכפלה של 3.'), ('=3(2x+3)', 'מוציאים את ה-3.')], form='fac', out='3', num='1', w='$6x = 3*2x$ ו-$9 = 3*3$.'),
    TRY('t-g2', 'פרקו: $x^2 + 5x$', 'x(x+5)', ['אין מספר משותף, אבל יש אות שמופיעה בשני האיברים.'], [('={1|x}*x+{1|x}*5', 'כל איבר כמכפלה של $x$.'), ('=x(x+5)', 'מוציאים את $x$.')], form='fac', out='x', num='2', w='$x^2 = x*x$.'),
    TRY('t-g3', 'פרקו: $4x^3 - 2x^2 + 8x$', '2x(2x^2-x+4)', ['הגורם המשותף הוא $2x$.', 'חלקו כל איבר ב-$2x$: מה נשאר?'], [('={1|2x}*2x^2-{1|2x}*x+{1|2x}*4', 'כל איבר כמכפלה של $2x$.'), ('=2x(2x^2-x+4)', 'מוציאים את $2x$.')], form='fac', out='2x', num='3', w='שלושה איברים בסוגריים, כמספר האיברים שהיו בביטוי.'),
    TRY('t-g4', 'פרקו: $10a^2b - 15ab^2$', '5ab(2a-3b)', ['מספר: 5. האות $a$: החזקה הנמוכה. האות $b$: החזקה הנמוכה.'], [('={1|5ab}*2a-{1|5ab}*3b', 'כל איבר כמכפלה של $5ab$.'), ('=5ab(2a-3b)', 'מוציאים את $5ab$.')], form='fac', out='5ab', num='4', w='הגורם המשותף כולל מספר ושתי אותיות.')],
    intro='הקלידו את הפירוק כמכפלה, למשל <span class="n">3(2x+3)</span>. המצגת בודקת גם שהוצאתם את הגורם הגדול ביותר.')

WORK('s-fac-dif', 'מסבירים יחד', 'פירוק בעזרת הנוסחה השלישית',
     ['**פרקו לגורמים את הביטוי הבא.** אין כאן גורם משותף, אבל יש הפרש של שני ריבועים.'],
     [('a^2-b^2 = (a+b)(a-b)', 'הנוסחה השלישית של הכפל המקוצר, הפעם מהסוף להתחלה.'),
      ('=x^2-5^2', 'מזהים שני ריבועים: 25 הוא $5^2$.'),
      ('~a = x, b = 5', 'התפקידים.'),
      ('=(x+5)(x-5)', 'מציבים בנוסחה.'),
      ('(x+5)(x-5) = x^2-5x+5x-25', 'בדיקה: פותחים סוגריים, והמכפלות האמצעיות מתבטלות.')],
     expr='x^2-25', size='sm',
     tip='סימני הזיהוי: שני איברים בלבד, מינוס ביניהם, וכל אחד מהם הוא ריבוע של משהו.')

TRYS('s-fac-dif-try', 'תרגול: הפרש ריבועים', 'תרגול: פרקו בעזרת $a^2 - b^2$', [
    TRY('t-h1', 'פרקו: $x^2 - 1$', '(x+1)(x-1)', ['1 הוא $1^2$.'], [('=x^2-1^2', 'שני ריבועים.'), ('=(x+1)(x-1)', 'לפי הנוסחה.')], form='fac', nb=2, num='1', w='$a = x$, $b = 1$.'),
    TRY('t-h2', 'פרקו: $9 - x^2$', '(3+x)(3-x)', ['9 הוא $3^2$. כאן $a = 3$ ו-$b = x$.'], [('=3^2-x^2', 'שני ריבועים.'), ('=(3+x)(3-x)', 'לפי הנוסחה.')], form='fac', nb=2, num='2', traps=[('(x+3)(x-3)', 'הסדר חשוב: $9 - x^2$ הוא $(3+x)(3-x)$. מה שכתבתם שווה $x^2 - 9$.')], w='$a = 3$, $b = x$.'),
    TRY('t-h3', 'פרקו: $4x^2 - 49$', '(2x+7)(2x-7)', ['$4x^2$ הוא הריבוע של $2x$, ו-49 הוא הריבוע של 7.'], [('=(2x)^2-7^2', 'שני ריבועים.'), ('=(2x+7)(2x-7)', 'לפי הנוסחה.')], form='fac', nb=2, num='3', w='$a = 2x$, $b = 7$.'),
    TRY('t-h4', 'פרקו: $64 - 16x^2$', '(8+4x)(8-4x)', ['64 הוא $8^2$, ו-$16x^2$ הוא הריבוע של $4x$.'], [('=8^2-(4x)^2', 'שני ריבועים.'), ('=(8+4x)(8-4x)', 'לפי הנוסחה.'), ('=16(2+x)(2-x)', 'אפשר להמשיך: מכל סוגריים יוצא גורם משותף 4, ויחד 16.')], form='fac', nb=2, num='4', w='$a = 8$, $b = 4x$. גם $16(2+x)(2-x)$ הוא פירוק נכון.')],
    intro='הקלידו את הפירוק כמכפלה של שני זוגות סוגריים, למשל <span class="n">(x+1)(x-1)</span>.')

WORK('s-fac-group', 'מסבירים יחד', 'כשסוגריים שלמים הם הגורם המשותף',
     ['**הוציאו גורם משותף מהביטוי הבא.** בודקים בנפרד: המספר, כל אות, והסוגריים.'],
     [('~6, 12', 'המספר הגדול ביותר שמחלק את שני המקדמים: 6.'),
      ('~a^3, a', 'האות $a$: החזקה הנמוכה היא $a$.'),
      ('~x^2, x^3', 'האות $x$: החזקה הנמוכה היא $x^2$.'),
      ('~(2x-3), (2x-3)^2', 'הסוגריים $(2x-3)$ מופיעים בשני האיברים. החזקה הנמוכה היא $(2x-3)$.'),
      ('={1|6ax^2(2x-3)}*a^2+{1|6ax^2(2x-3)}*2x(2x-3)', 'כותבים כל איבר כמכפלה של הגורם המשותף במה שנשאר.'),
      ('={1|6ax^2(2x-3)}(a^2+2x(2x-3))', 'מוציאים את הגורם המשותף.')],
     expr='6a^3x^2(2x-3)+12ax^3(2x-3)^2', size='xs', layout='narq',
     tip='סוגריים שלמים מתנהגים כמו אות אחת. אם הם מופיעים בכל האיברים, אפשר להוציא אותם.')

TRYBIG('s-fac-e', 'נסו לבד', 'גורם משותף שהוא חזקה שלמה',
       ['**פרקו לגורמים את הביטוי הבא.**', 'האות $e$ מסמנת כאן מספר קבוע, שערכו בערך 2.718. התייחסו אל החזקה $e^(2x+1)$ כאל גורם אחד, כמו אל אות.'],
       'x*e^(2x+1)(6-5x)', expr='6x*e^(2x+1)-5x^2*e^(2x+1)', form='fac', out='x*e^(2x+1)', vars_='xe',
       hints=['מה מופיע בכפל בשני האיברים? האות $x$, והחזקה $e^(2x+1)$.', 'אחרי שמוציאים את $x*e^(2x+1)$, מהאיבר הראשון נשאר 6 ומהשני נשאר $5x$.'],
       steps=[('~', 'אין מספר שמחלק גם את 6 וגם את 5, פרט ל-1.'),
              ('~x, x^2', 'האות $x$: החזקה הנמוכה היא $x$.'),
              ('~', 'החזקה $e^(2x+1)$ מופיעה בשני האיברים, כפי שהיא.'),
              ('={1|x*e^(2x+1)}*6-{1|x*e^(2x+1)}*5x', 'כותבים כל איבר כמכפלה של הגורם המשותף במה שנשאר.'),
              ('={1|x*e^(2x+1)}(6-5x)', 'מוציאים את הגורם המשותף.')],
       w='הגורם המשותף הוא $x*e^(2x+1)$, ובסוגריים נשאר $6 - 5x$.', tip='ביטוי שנראה מאיים הוא לעיתים קרובות גורם אחד שחוזר. מזהים אותו, ומתייחסים אליו כאל אות.')

SUMMARY('s-sum7', 'מה למדנו בחלק 7', [
    ('פירוק לגורמים', 'כתיבת סכום כמכפלה. זו הפעולה ההפוכה לפתיחת סוגריים.'),
    ('גורם משותף', 'המספר הגדול ביותר שמחלק את כל המקדמים, וכל אות שמופיעה בכל האיברים, בחזקה הנמוכה ביותר שלה.'),
    ('הפרש ריבועים', '$a^2 - b^2 = (a+b)(a-b)$. שני איברים, מינוס ביניהם, ושניהם ריבועים.'),
    ('בדיקה', 'פותחים את הסוגריים. אם חזרנו לביטוי המקורי, הפירוק נכון.')])

# ================================================================ part 8
opener(8, 'סיכום ותרגילים מסכמים', 'כל הכלים של המפגש בדף אחד, ואחריו תרגול: בכיתה ובבית',
       ['דף הכללים של המפגש', 'ארבעה צעדים לפישוט כל ביטוי', 'תרגילים מסכמים 1 עד 6, בכיתה, ככל שנספיק', 'תרגול עצמי לבית, לפי נושאים'], 10)

S('s-rules', 'דף הכללים', 'דף הכללים של מפגש 1',
  '<div class="rules">'
  + CARD('<b class="ct">סדר פעולות החשבון</b><p>סוגריים, חזקות ושורשים, כפל וחילוק, חיבור וחיסור. באותה רמה: משמאל לימין.</p>' + VEQ('-5^2 = -25') + VEQ('(-5)^2 = 25'))
  + CARD('<b class="ct">כינוס איברים דומים</b><p>מחברים מקדמים של איברים עם אותן אותיות ואותן חזקות.</p>' + VEQ('6x+3-2x-5-x = 3x-2'))
  + CARD('<b class="ct">חוקי חזקות</b>' + VEQ('x^a*x^b = x^(a+b)') + VEQ('(x^a)^b = x^(a*b)') + VEQ('(a*b)^n = a^n*b^n'))
  + CARD('<b class="ct">פתיחת סוגריים</b>' + VEQ('a(b+c) = ab+ac') + VEQ('-(a-b) = -a+b') + VEQ('(a+b)(c+d) = ac+ad+bc+bd'))
  + CARD('<b class="ct">נוסחאות הכפל המקוצר</b>' + VEQ('(a+b)^2 = a^2+2ab+b^2') + VEQ('(a-b)^2 = a^2-2ab+b^2') + VEQ('(a+b)(a-b) = a^2-b^2'))
  + CARD('<b class="ct">פירוק לגורמים</b><p>גורם משותף גדול ביותר, או הפרש ריבועים.</p>' + VEQ('4x^3-4x^2 = 4x^2(x-1)') + VEQ('x^2-25 = (x+5)(x-5)'))
  + '</div>', kick=KICK('סיכום המפגש'))

S('s-flow', 'ארבעה צעדים', 'איך מפשטים ביטוי: ארבעה צעדים, תמיד באותו סדר',
  '<div class="flow4">'
  + ST(1, '<div class="fn">1</div><b>חזקות של סוגריים</b><p>פותחים חזקות לפי חוקי החזקות או לפי נוסחאות הכפל המקוצר.</p>' + EQ('(2x)^2 = 4x^2'), cls='card pop')
  + ST(2, '<div class="fn">2</div><b>פתיחת סוגריים</b><p>כופלים, ושמים לב למינוס שלפני הסוגריים.</p>' + EQ('-(x-3) = -x+3'), cls='card pop')
  + ST(3, '<div class="fn">3</div><b>כינוס</b><p>מחברים איברים דומים, משפחה אחר משפחה.</p>' + EQ('4x^2-x+3+x = 4x^2+3'), cls='card pop')
  + ST(4, '<div class="fn">4</div><b>סידור ובדיקה</b><p>כותבים מהחזקה הגבוהה לנמוכה, ובודקים בהצבה של מספר פשוט.</p>' + EQ('x = 1'), cls='card pop')
  + '</div>'
  + BAND('tip', 'בדיקה בהצבה: בוחרים מספר פשוט, למשל $x = 1$ או $x = 2$, ומציבים אותו בביטוי המקורי ובתוצאה. אם שני הערכים שונים, יש טעות בדרך.', 5),
  kick=KICK('סיכום המפגש'))

S('s-split', 'מה בכיתה ומה בבית', 'התרגול: מה פותרים בכיתה, ומה בבית',
  '<div class="splitg">'
  + CARD('<h4>בכיתה: תרגילים מסכמים 1 עד 6</h4><ul><li>שישה תרגילים, אחד מכל סוג שלמדנו. פותרים ככל שנספיק.</li><li>כל תרגיל בשקף משלו, עם השאלה המלאה.</li><li>מנסים לבד, ואז נעזרים ב״רמז״ או ב״פתרון בשלבים״.</li><li>תרגיל שלא הספקנו בכיתה עובר לתרגול בבית.</li></ul>')
  + CARD('<h4>בבית: תרגול עצמי, לפי נושאים</h4><ul><li>השקפים שאחרי התרגילים המסכמים, עד סוף המצגת.</li><li>גם בהם: בדיקה מיידית, רמזים ופתרון בשלבים.</li><li>' + TX('אחריהם: חוברת התרגילים של מפגש 1, עם פתרונות מלאים באתר הקורס.') + '</li><li>התרגילים אינם להגשה. הם ההכנה לבחינה.</li></ul>')
  + '</div>'
  + BAND('dg', 'אלגברה נלמדת בידיים. מי שפותר את התרגילים בעצמו, על דף, יגיע למפגש הבא מוכן למשוואות.'),
  kick=KICK('תרגול'))

TRYBIG('x-1', 'תרגיל מסכם 1', 'תרגיל מסכם 1: סדר פעולות חשבון',
       ['**חשבו את ערך הביטוי הבא.** כתבו שורה חדשה לכל פעולה.'], '-2', expr='4-2(3-5)^2+18÷3^2',
       hints=['התחילו מהסוגריים: $3 - 5$.', 'אחר כך שתי החזקות, אחר כך הכפל והחילוק, ובסוף חיבור וחיסור משמאל לימין.'],
       steps=[('=4-2(-2)^2+18÷3^2', 'סוגריים: $3 - 5 = -2$.'), ('=4-2*4+18÷9', 'חזקות: $(-2)^2 = 4$ ו-$3^2 = 9$.'), ('=4-8+2', 'כפל וחילוק: $2*4 = 8$ ו-$18÷9 = 2$.'), ('=-2', 'חיבור וחיסור משמאל לימין: $4 - 8 = -4$, ואז $-4 + 2 = -2$.')],
       traps=[('10', 'אל תחסרו $4 - 2$ בהתחלה. הכפל $2*4$ קודם לחיסור.'), ('14', '$(-2)^2$ הוא 4 חיובי, אבל לפניו כתוב $-2$ כפול: $-2*4 = -8$.'), ('-6', 'חיבור וחיסור מבצעים משמאל לימין: קודם $4 - 8$, ואז מוסיפים 2.')],
       w='סוגריים, חזקות, כפל וחילוק, ולבסוף חיבור וחיסור. ערך הביטוי: $-2$.', tip='בתרגיל ארוך, סמנו בעיגול את הפעולה שאתם מבצעים בכל שורה. כל השאר מועתק כפי שהוא.')

TRYBIG('x-2', 'תרגיל מסכם 2', 'תרגיל מסכם 2: הצבה בביטוי של רווח',
       ['**סדנת קרמיקה מוכרת כרטיסים למפגש. הרווח של הסדנה, בש״ח, כשנמכרים $x$ כרטיסים, נתון בביטוי הבא.**', '**מהו הרווח כשנמכרים 10 כרטיסים?**'], '150', expr='-x^2+40x-150',
       hints=['הציבו 10 במקום כל $x$, בסוגריים.', '$-x^2$ פירושו מינוס של $x^2$: קודם החזקה, ורק אז המינוס.'],
       steps=[('~-(10)^2+40*(10)-150', 'מציבים 10 במקום $x$, בסוגריים.'), ('=-100+400-150', 'חזקה ואז כפל: $10^2 = 100$, והמינוס שלפניה נשאר. $40*10 = 400$.'), ('=150', 'חיבור וחיסור משמאל לימין. הרווח הוא 150 ש״ח.')],
       traps=[('350', '$-x^2$ פירושו $-(x^2)$. כאשר $x = 10$ מקבלים $-100$, ולא $+100$.')],
       w='$-100 + 400 - 150 = 150$ ש״ח.', tip='המינוס שלפני $x^2$ אינו חלק מהחזקה. זו המלכודת של $-5^2$, בתחפושת.')

TRYBIG('x-3', 'תרגיל מסכם 3', 'תרגיל מסכם 3: פישוט ביטוי של רווח',
       ['**חנות אינטרנטית מוכרת תיקים. ההכנסה ממכירת $x$ תיקים היא $120x$ ש״ח. עלות הקנייה שלהם היא $45x + 900$ ש״ח, ודמי המשלוח הם $5x$ ש״ח.**', '**הרווח הוא ההכנסה, פחות עלות הקנייה, פחות המשלוח. פשטו את ביטוי הרווח:**'], '70x-900', expr='120x-(45x+900)-5x',
       hints=['פתחו קודם את הסוגריים. המינוס שלפניהם הופך את שני הסימנים.', 'אחר כך כנסו את שלושת האיברים עם $x$.'],
       steps=[('=120x-45x-900-5x', 'פותחים סוגריים: $+45x$ הופך ל-$-45x$, ו-$+900$ הופך ל-$-900$.'), ('120-45-5 = 70', 'משפחת $x$.'), ('=70x-900', 'ביטוי הרווח המפושט.')],
       traps=[('70x+900', 'המינוס שלפני הסוגריים הופך גם את $+900$ ל-$-900$.'), ('80x-900', 'גם $5x$ מופחת: $120 - 45 - 5 = 70$.'), ('75x-900', 'גם דמי המשלוח $5x$ מופחתים.')],
       w='כל תיק מוסיף 70 ש״ח לרווח, ו-900 ש״ח הם עלות קבועה.', tip='הביטוי המפושט מספר סיפור: 70 הוא הרווח מכל תיק, ו-900 הוא מה שצריך לכסות לפני שמרוויחים.')

TRYBIG('x-4', 'תרגיל מסכם 4', 'תרגיל מסכם 4: חוקי חזקות',
       ['**פשטו את הביטוי הבא, וכתבו אותו כאיבר אחד.**'], '18x^5y^5', expr='(3x^2y)^2*2xy^3', terms=1,
       hints=['קודם פתחו את הסוגריים: כל גורם בריבוע.', 'אחר כך כפלו: מספרים, חזקות של $x$, וחזקות של $y$.'],
       steps=[('(3x^2y)^2 = 3^2*(x^2)^2*y^2 = 9x^4y^2', 'חזקה של מכפלה: כל גורם מקבל את המעריך 2.'), ('=9x^4y^2*2xy^3', 'מציבים בביטוי.'), ('9*2 = 18', 'המספרים.'), ('x^4*x = x^5', 'החזקות של $x$. ל-$x$ בלי מעריך יש מעריך 1.'), ('y^2*y^3 = y^5', 'החזקות של $y$.'), ('=18x^5y^5', 'התוצאה.')],
       traps=[('6x^5y^5', 'גם ה-3 בריבוע: $3^2 = 9$, ואז $9*2 = 18$.'), ('18x^4y^5', '$x^4*x = x^5$: ל-$x$ יש מעריך 1.'), ('18x^3y^5', 'בתוך הסוגריים: $(x^2)^2 = x^4$, כופלים את המעריכים.')],
       w='$9*2 = 18$, $x^(4+1) = x^5$, $y^(2+3) = y^5$.', tip='שלושה חוקים בתרגיל אחד. עובדים לפי הסדר: קודם הסוגריים, אחר כך הכפל.')

TRYBIG('x-5', 'תרגיל מסכם 5', 'תרגיל מסכם 5: כפל מקוצר ופתיחת סוגריים',
       ['**פשטו את הביטוי הבא.**'], '2x^2+13x+30', expr='(x+6)^2-(x+3)(2-x)',
       hints=['פתחו כל חלק בנפרד: את $(x+6)^2$ בנוסחה, ואת $(x+3)(2-x)$ בארבע מכפלות.', 'לפני המכפלה השנייה יש מינוס. השאירו אותה בסוגריים עד שתסיימו לפתוח אותה.'],
       steps=[('(x+6)^2 = x^2+12x+36', 'ריבוע של סכום: $a = x$, $b = 6$.'), ('(x+3)(2-x) = 2x-x^2+6-3x', 'ארבע מכפלות.'), ('(x+3)(2-x) = -x^2-x+6', 'מכנסים.'), ('=x^2+12x+36-(-x^2-x+6)', 'מציבים. המכפלה כולה נשארת בסוגריים, כי לפניה מינוס.'), ('=x^2+12x+36+x^2+x-6', 'המינוס הופך את כל שלושת הסימנים.'), ('=2x^2+13x+30', 'מכנסים.')],
       traps=[('11x+42', 'המינוס שלפני המכפלה חל על כל איבריה. השאירו אותה בסוגריים עד שתפתחו אותם.'), ('2x^2+13x+42', 'המינוס חל גם על ה-6: $36 - 6 = 30$.'), ('2x^2+11x+30', 'המינוס הופך את $-x$ ל-$+x$: $12x + x = 13x$.')],
       w='שני חלקים שנפתחו בנפרד, ומינוס שהפך את כל הסימנים של החלק השני.', tip='מינוס לפני מכפלה של סוגריים: פותחים קודם את המכפלה בתוך סוגריים, ורק אז הופכים סימנים.')

TRYBIG('x-6', 'תרגיל מסכם 6', 'תרגיל מסכם 6: פירוק מלא לגורמים',
       ['**פרקו לגורמים את הביטוי הבא, ככל האפשר.**'], '3x(x+2)(x-2)', expr='3x^3-12x', form='fac', out='3x', nb=2,
       hints=['התחילו מגורם משותף: מספר, ואות.', 'הסתכלו על מה שנשאר בסוגריים. האם זה הפרש של שני ריבועים?'],
       steps=[('={1|3x}*x^2-{1|3x}*4', 'גורם משותף: המספר 3, והאות $x$ בחזקה הנמוכה.'), ('=3x(x^2-4)', 'מוציאים את $3x$.'), ('x^2-4 = x^2-2^2 = (x+2)(x-2)', 'בסוגריים נשאר הפרש של שני ריבועים.'), ('=3x(x+2)(x-2)', 'הפירוק המלא.')],
       w='שני שלבים: גורם משותף $3x$, ואחריו הפרש ריבועים.', tip='סדר קבוע בפירוק: קודם גורם משותף, ורק אחר כך בודקים אם מה שנשאר מתאים לנוסחה.')

S('s-home', 'תרגול עצמי לבית', 'תרגול עצמי לבית: מכאן ועד סוף המצגת',
  '<div class="row eq2"><div class="col">'
  + CARD('<b class="ct">איך עובדים בבית</b><ol class="lg"><li>פותרים על דף, שורה לכל פעולה.</li><li>מקלידים את התשובה ובודקים.</li><li>טעיתם? קוראים את המשוב, ומנסים שוב לפני שפותחים רמז.</li><li>״פתרון בשלבים״ הוא המוצא האחרון, שלב אחד בכל פעם.</li></ol>')
  + BAND('note', 'אחרי השקפים האלה: חוברת התרגילים של מפגש 1 באתר הקורס, עם פתרון מלא בשלבים לכל תרגיל.')
  + '</div><div class="col">'
  + TABLE(['הנושא', 'מה יש בשקפים'], [['סדר פעולות', 'פעילות נוספת של ״מה עושים קודם״'], ['כינוס איברים', 'ארבעה תרגילים'], ['חוקי חזקות', 'דוגמה עם מקדם שלילי, וארבעה תרגילים'], ['פתיחת סוגריים ופישוט', 'שישה תרגילים'], ['כפל מקוצר', 'שמונה תרגילים, מהקל אל הקשה'], ['פירוק לגורמים', 'ארבעה תרגילים, ושתי דוגמאות מתקדמות'], ['תרגילים משולבים', 'ארבעה תרגילים']])
  + '</div></div>', kick=KICK('תרגול עצמי'))

TRYS('h-a', 'לבית: כפל מקוצר, מתקדם', 'תרגול: כפל מקוצר עם כמה אותיות', [
    TRY('t-h7', 'פתחו: $(2x^2 - y)^2$', '4x^4-4x^2y+y^2', ['$a = 2x^2$, $b = y$.', '$(2x^2)^2 = 4x^4$.'], [('~a = 2x^2, b = y', 'מזהים.'), ('=(2x^2)^2-2*2x^2*y+y^2', 'מציבים בנוסחה $(a-b)^2 = a^2 - 2ab + b^2$.'), ('=4x^4-4x^2y+y^2', 'התוצאה.')], num='1',
        traps=[('4x^4-y^2', 'חסר האיבר האמצעי $2ab$, והאיבר האחרון חיובי.'), ('2x^4-4x^2y+y^2', '$(2x^2)^2 = 4x^4$.')], w='$(2x^2)^2 = 4x^4$, ו-$2ab = 4x^2y$.'),
    TRY('t-h8', 'פתחו: $(2x^2y - 4z^3)^2$', '4x^4y^2-16x^2yz^3+16z^6', ['$a = 2x^2y$, $b = 4z^3$.', '$b^2 = (4z^3)^2 = 16z^6$.'], [('~a = 2x^2y, b = 4z^3', 'מזהים.'), ('(2x^2y)^2 = 4x^4y^2', 'הריבוע של $a$.'), ('2*2x^2y*4z^3 = 16x^2yz^3', 'פעמיים המכפלה.'), ('(4z^3)^2 = 16z^6', 'הריבוע של $b$.'), ('=4x^4y^2-16x^2yz^3+16z^6', 'לפי הנוסחה $a^2 - 2ab + b^2$.')], num='2',
        traps=[('4x^4y^2-8x^2yz^3+16z^6', 'פעמיים המכפלה: $2*2*4 = 16$.')], w='שלושה איברים, כל אחד חושב בנפרד.'),
    TRY('t-h9', 'פתחו: $(3xb^3 - 3a)^2$', '9x^2b^6-18xb^3a+9a^2', ['כאן ה-$a$ של הנוסחה הוא $3xb^3$, וה-$b$ של הנוסחה הוא $3a$.'], [('(3xb^3)^2 = 9x^2b^6', 'הריבוע של האיבר הראשון.'), ('2*3xb^3*3a = 18xb^3a', 'פעמיים המכפלה.'), ('(3a)^2 = 9a^2', 'הריבוע של האיבר השני.'), ('=9x^2b^6-18xb^3a+9a^2', 'לפי הנוסחה.')], num='3',
        traps=[('9x^2b^6-9xb^3a+9a^2', 'פעמיים המכפלה: $2*3*3 = 18$.')], w='האותיות $a$ ו-$b$ בתרגיל אינן ה-$a$ וה-$b$ של הנוסחה.'),
    TRY('t-h10', 'פשטו: $3(2x - 7)^2 - (4x - 20)$', '12x^2-88x+167', ['קודם $(2x-7)^2 = 4x^2 - 28x + 49$, ורק אחר כך הכפל ב-3.', 'המינוס שלפני הסוגריים האחרונים הופך את $-20$ ל-$+20$.'], [('(2x-7)^2 = 4x^2-28x+49', 'ריבוע של הפרש.'), ('=3(4x^2-28x+49)-(4x-20)', 'מציבים.'), ('=12x^2-84x+147-4x+20', 'פותחים את שני זוגות הסוגריים.'), ('=12x^2-88x+167', 'מכנסים.')], num='4',
        traps=[('12x^2-88x+127', 'המינוס הופך את $-20$ ל-$+20$: $147 + 20 = 167$.'), ('12x^2-80x+167', '$-84x - 4x = -88x$.')], w='חזקה, כפל ב-3, היפוך סימנים, וכינוס.')],
    kick='תרגול עצמי')

TRYS('h-b', 'לבית: תרגילים משולבים', 'תרגול: תרגילים משולבים', [
    TRY('t-h11', 'פשטו: $(x^2 + 2)(3x - 2) - 2(2 - 2x)(1 - 3x^2)$', '-9x^3+10x^2+10x-8', ['פתחו כל מכפלה בנפרד, ורק אז כפלו את השנייה ב-$-2$.', '$(2-2x)(1-3x^2) = 2 - 6x^2 - 2x + 6x^3$.'], [('(x^2+2)(3x-2) = 3x^3-2x^2+6x-4', 'המכפלה הראשונה.'), ('(2-2x)(1-3x^2) = 2-6x^2-2x+6x^3', 'המכפלה השנייה.'), ('-2(2-6x^2-2x+6x^3) = -4+12x^2+4x-12x^3', 'כופלים ב-$-2$: כל הסימנים מתהפכים.'), ('=-9x^3+10x^2+10x-8', 'מכנסים את שמונת האיברים.')], num='1',
        traps=[('15x^3-14x^2+2x', 'ה-$-2$ הופך את כל הסימנים של המכפלה השנייה.')], w='שתי מכפלות, כפל ב-$-2$, וכינוס.'),
    TRY('t-h12', 'פשטו: $(x^2 - 2)(4x + 5)(2 - 2x)$', '-8x^4-2x^3+26x^2+4x-20', ['כפלו קודם שני זוגות סוגריים, ואת התוצאה כפלו בזוג השלישי.', '$(x^2-2)(4x+5) = 4x^3 + 5x^2 - 8x - 10$.'], [('(x^2-2)(4x+5) = 4x^3+5x^2-8x-10', 'שני הזוגות הראשונים.'), ('=(4x^3+5x^2-8x-10)(2-2x)', 'נשאר לכפול בזוג השלישי.'), ('=8x^3+10x^2-16x-20-8x^4-10x^3+16x^2+20x', 'כל אחד מארבעת האיברים כפול 2, ואחר כך כפול $-2x$.'), ('=-8x^4-2x^3+26x^2+4x-20', 'מכנסים.')], num='2', w='שלושה זוגות סוגריים כופלים בשני שלבים.'),
    TRY('t-h13', 'פרקו: $8x^2y - 12xy^2 + 4xy$', '4xy(2x-3y+1)', ['מספר: 4. כל אחת מהאותיות, בחזקה הנמוכה.', 'האיבר השלישי הוא הגורם המשותף עצמו. מה נשאר ממנו?'], [('={1|4xy}*2x-{1|4xy}*3y+{1|4xy}*1', 'כל איבר כמכפלה של $4xy$.'), ('=4xy(2x-3y+1)', 'מוציאים את $4xy$. מהאיבר השלישי נשאר 1.')], form='fac', out='4xy', num='3', w='מהאיבר $4xy$ נשאר 1 בסוגריים.'),
    TRY('t-h14', 'חשבו: $5 - 3(2 - 4)^3 ÷ 6$', '9', ['סוגריים, ואז חזקה: $(-2)^3$ שלילי.', 'כפל וחילוק משמאל לימין, ובסוף החיסור. מינוס מינוס נותן פלוס.'], [('=5-3(-2)^3÷6', 'סוגריים: $2 - 4 = -2$.'), ('=5-3*(-8)÷6', 'חזקה: $(-2)^3 = -8$.'), ('=5-(-24)÷6', 'כפל: $3*(-8) = -24$.'), ('=5-(-4)', 'חילוק: $-24÷6 = -4$.'), ('=9', 'חיסור של מספר שלילי הוא חיבור: $5 + 4$.')], num='4',
        traps=[('1', 'חיסור של מספר שלילי הוא חיבור: $5 - (-4) = 9$.'), ('-27', 'אל תחסרו $5 - 3$ בהתחלה. הכפל והחילוק קודמים.')], w='$5 - (-4) = 9$.')],
    kick='תרגול עצמי')
